/// <summary>One column per PostgreSQL type family</summary>
[Table("type_zoo", Schema = "public")]
public sealed class TypeZoo
{
    [Key]
    [Column("id")]
    public Guid Id { get; set; }

    [Column("small")]
    public short? Small { get; set; }

    [Column("big")]
    public long? Big { get; set; }

    [Column("ratio")]
    public float? Ratio { get; set; }

    [Column("score")]
    public double? Score { get; set; }

    [Column("price", TypeName = "money")]
    public decimal? Price { get; set; }

    [Column("code")]
    [StringLength(20)]
    public string? Code { get; set; }

    [Column("day")]
    public DateOnly? Day { get; set; }

    [Column("at_local", TypeName = "timestamp(3) without time zone")]
    public DateTime? AtLocal { get; set; }

    [Column("opens")]
    public TimeOnly? Opens { get; set; }

    [Column("opens_tz", TypeName = "time with time zone")]
    public DateTimeOffset? OpensTz { get; set; }

    // NpgsqlInterval for month parts (TimeSpan has no months)
    [Column("wait")]
    public TimeSpan? Wait { get; set; }

    [Column("doc", TypeName = "json")]
    public string? Doc { get; set; }

    [Column("spec", TypeName = "xml")]
    public string? Spec { get; set; }

    [Column("ip")]
    public IPAddress? Ip { get; set; }

    [Column("mac")]
    public PhysicalAddress? Mac { get; set; }

    // TODO: point is read as object; map it to NpgsqlPoint (NpgsqlTypes).
    [Column("location")]
    public object? Location { get; set; }

    // TODO: tsvector is read as object; map it to NpgsqlTsVector (NpgsqlTypes).
    [Column("search")]
    public object? Search { get; set; }

    // TODO: tstzrange is read as object; map it to NpgsqlRange<T> (NpgsqlTypes).
    [Column("during")]
    public object? During { get; set; }

    [Column("counts")]
    public int[]? Counts { get; set; }

    // enum: new, paid, shipped, cancelled
    [Column("statuses")]
    public string[]? Statuses { get; set; }

    /// <summary>Reserved word as a column name</summary>
    [Column("user")]
    public string? User { get; set; }

    /// <summary>Mixed case needs quoting</summary>
    public string? CamelCase { get; set; }
}

