public sealed class CustomerOrdersRow
{
    public long Id { get; set; }

    public string Name { get; set; } = "";

    public decimal Total { get; set; }

    public DateTimeOffset? OrderDate { get; set; }

    // enum: new, paid, shipped, cancelled
    public string Status { get; set; } = "";
}

public static class CustomerOrdersQuery
{
    public const string Sql = """
        SELECT c.id, c.name, o.total, o.order_date, o.status
        FROM customers c
        JOIN orders o ON o.customer_id = c.id
        WHERE c.id = @p1 AND o.total > @p2
        ORDER BY o.order_date DESC
        """;

    public static async Task<IReadOnlyList<CustomerOrdersRow>> GetCustomerOrdersAsync(this NpgsqlConnection db, long p1, decimal p2, CancellationToken ct = default)
    {
        await using var cmd = db.CreateCommand();
        cmd.CommandText = Sql;
        cmd.Parameters.AddWithValue("p1", p1);
        cmd.Parameters.AddWithValue("p2", p2);
        if (db.State != ConnectionState.Open) await db.OpenAsync(ct);
        await using var r = await cmd.ExecuteReaderAsync(ct);
        var list = new List<CustomerOrdersRow>();
        while (await r.ReadAsync(ct))
        {
            list.Add(new CustomerOrdersRow
            {
                Id = r.GetInt64(0),
                Name = r.GetString(1),
                Total = r.GetDecimal(2),
                OrderDate = r.IsDBNull(3) ? null : r.GetFieldValue<DateTimeOffset>(3),
                Status = r.GetString(4),
            });
        }
        return list;
    }
}

