        await using var reader = await cmd.ExecuteReaderAsync(ct);
        var rows = new List<OrdersOfRow>();
        while (await reader.ReadAsync(ct)) rows.Add(MapOrdersOfRow(reader));
        return rows;
    }

    private static OrdersOfRow MapOrdersOfRow(DbDataReader r) => new()
    {
        Id = r.IsDBNull(0) ? null : r.GetInt64(0),
        OrderDate = r.IsDBNull(1) ? null : r.GetFieldValue<DateTimeOffset>(1),
        Total = r.IsDBNull(2) ? null : r.GetDecimal(2),
    };

    /// <summary>Calls public.add_order_line.</summary>
    public static async Task<AddOrderLineResult> AddOrderLineAsync(this NpgsqlConnection db, long orderId, int productId, int? qty = null, int? lineNo = null, CancellationToken ct = default)
    {
        await using var cmd = db.CreateCommand();
        var callArgs = new List<string> { "@p_order_id", "@p_product_id" };
        cmd.Parameters.Add(new NpgsqlParameter("p_order_id", NpgsqlDbType.Bigint) { Value = orderId });
        cmd.Parameters.Add(new NpgsqlParameter("p_product_id", NpgsqlDbType.Integer) { Value = productId });
        if (qty is not null)
        {
            callArgs.Add("p_qty => @p_qty");
            cmd.Parameters.Add(new NpgsqlParameter("p_qty", NpgsqlDbType.Integer) { Value = qty });
        }
        if (lineNo is not null)
        {
            callArgs.Add("p_line_no => @p_line_no");
            cmd.Parameters.Add(new NpgsqlParameter("p_line_no", NpgsqlDbType.Integer) { Value = (object?)lineNo ?? DBNull.Value });
        }
        cmd.CommandText = $"CALL public.add_order_line({string.Join(", ", callArgs)})";
        if (db.State != ConnectionState.Open) await db.OpenAsync(ct);
        // OUT / INOUT values come back as one row.
        await using var reader = await cmd.ExecuteReaderAsync(ct);
        await reader.ReadAsync(ct);
        return new AddOrderLineResult(reader.IsDBNull(0) ? null : reader.GetInt32(0));
    }
}
